import re
from pathlib import Path
CJK=re.compile(r'[\u3400-\u4dbf\u4e00-\u9fff]+'); LAT=re.compile(r'[a-z0-9]+')
def tokens(text):
    out=set()
    for run in CJK.findall(text):
        if len(run)==1: out.add(run)
        else: out.update(run[i:i+2] for i in range(len(run)-1))
    out.update(LAT.findall(text.lower()))
    return out
docs_dir=Path('tests/fixtures/knowledge_docs')
toks={p.name:tokens(p.read_text(encoding='utf-8')) for p in docs_dir.glob('*.md')}
from collections import Counter
df=Counter()
for t in toks.values():
    df.update(t.keys())
# tokens sorted by df desc, len>=2
common=[t for t,c in df.most_common() if len(t)>=2 and c>=4]
targets=['after-sales-return-policy.md','product-model-specs.md','security-incident-response.md','billing-invoice.md','ops-backup-restore.md']
for target in targets:
    good=[t for t in common if t not in toks[target]]
    print(target, '->', good[:60])
PY", "description": "Find common tokens usable in semantic queries"}

